"""Small transactional store. All persisted payloads are generated by this demo."""

import json
import sqlite3
from contextlib import contextmanager
from datetime import UTC, datetime
from pathlib import Path

from .planner import NotFound


def now() -> str:
    return datetime.now(UTC).isoformat(timespec="milliseconds")


class Store:
    def __init__(self, path: str):
        self.path = path
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        with self.transaction() as db:
            db.executescript("""
                CREATE TABLE IF NOT EXISTS runs (
                    id TEXT PRIMARY KEY,
                    request_key TEXT UNIQUE NOT NULL,
                    fingerprint TEXT NOT NULL,
                    goal TEXT NOT NULL,
                    plan TEXT NOT NULL,
                    status TEXT NOT NULL,
                    approved_hash TEXT,
                    created_at TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS steps (
                    run_id TEXT NOT NULL REFERENCES runs(id),
                    position INTEGER NOT NULL,
                    tool TEXT NOT NULL,
                    title TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'pending',
                    attempts INTEGER NOT NULL DEFAULT 0,
                    result TEXT,
                    PRIMARY KEY (run_id, position)
                );
                CREATE TABLE IF NOT EXISTS events (
                    seq INTEGER PRIMARY KEY AUTOINCREMENT,
                    run_id TEXT NOT NULL REFERENCES runs(id),
                    kind TEXT NOT NULL,
                    payload TEXT NOT NULL,
                    created_at TEXT NOT NULL
                );
                CREATE INDEX IF NOT EXISTS events_run_seq ON events(run_id, seq);
                CREATE TABLE IF NOT EXISTS operations (
                    key TEXT PRIMARY KEY,
                    run_id TEXT NOT NULL REFERENCES runs(id),
                    result TEXT NOT NULL
                );
            """)

    @contextmanager
    def transaction(self):
        db = sqlite3.connect(self.path, timeout=10, isolation_level=None)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA foreign_keys=ON")
        try:
            db.execute("BEGIN IMMEDIATE")
            yield db
            db.commit()
        except BaseException:
            db.rollback()
            raise
        finally:
            db.close()

    @staticmethod
    def event(db, run_id: str, kind: str, **payload):
        db.execute(
            "INSERT INTO events(run_id,kind,payload,created_at) VALUES(?,?,?,?)",
            (run_id, kind, json.dumps(payload), now()),
        )

    @staticmethod
    def snapshot(db, run_id: str) -> dict:
        row = db.execute("SELECT * FROM runs WHERE id=?", (run_id,)).fetchone()
        if row is None:
            raise NotFound("Run not found.")
        result = {k: row[k] for k in ("id", "goal", "status", "approved_hash", "created_at")}
        result["plan"] = json.loads(row["plan"])
        result["steps"] = [
            {**dict(s), "result": json.loads(s["result"]) if s["result"] else None}
            for s in db.execute("SELECT * FROM steps WHERE run_id=? ORDER BY position", (run_id,))
        ]
        return result

    def get(self, run_id: str) -> dict:
        with self.transaction() as db:
            return self.snapshot(db, run_id)

    def recent(self) -> list[dict]:
        with self.transaction() as db:
            return [
                self.snapshot(db, row["id"])
                for row in db.execute("SELECT id FROM runs ORDER BY rowid DESC LIMIT 30").fetchall()
            ]

    def ready(self) -> list[str]:
        with self.transaction() as db:
            return [
                r[0]
                for r in db.execute(
                    "SELECT id FROM runs WHERE status IN ('queued','running') ORDER BY rowid"
                )
            ]

    def events(self, run_id: str, after: int = 0) -> list[dict]:
        with self.transaction() as db:
            if not db.execute("SELECT 1 FROM runs WHERE id=?", (run_id,)).fetchone():
                raise NotFound("Run not found.")
            return [
                {**dict(row), "payload": json.loads(row["payload"])}
                for row in db.execute(
                    "SELECT * FROM events WHERE run_id=? AND seq>? ORDER BY seq", (run_id, after)
                )
            ]
